-- Generated Android device catalog seed for NAPL (Phone, Tablet, Handheld)
-- Total unique devices: 18384
BEGIN;

ALTER TABLE public.devices
    ADD COLUMN IF NOT EXISTS manufacturer text NOT NULL DEFAULT '',
    ADD COLUMN IF NOT EXISTS model text NOT NULL DEFAULT '',
    ADD COLUMN IF NOT EXISTS soc text NOT NULL DEFAULT '',
    ADD COLUMN IF NOT EXISTS device_type text NOT NULL DEFAULT 'phone';

CREATE TEMP TABLE _napl_seed_devices (
    id text PRIMARY KEY,
    name text NOT NULL,
    manufacturer text NOT NULL,
    model text NOT NULL,
    soc text NOT NULL,
    device_type text NOT NULL
) ON COMMIT DROP;


SELECT id, name, manufacturer, model, soc, device_type
FROM _napl_seed_devices
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    manufacturer = EXCLUDED.manufacturer,
    model = EXCLUDED.model,
    soc = EXCLUDED.soc,
    device_type = EXCLUDED.device_type;

-- Remove obsolete/duplicate legacy devices only if they have no compatibility reports
DELETE FROM public.devices d
WHERE NOT EXISTS (
    SELECT 1 FROM _napl_seed_devices s WHERE s.id = d.id
)
AND NOT EXISTS (
    SELECT 1 FROM public.compatibility_reports r WHERE r.device_id = d.id
);

COMMIT;
